codeSample:
# ① 发起批量移动
POST /v1/mailboxes/{mailboxId}/bulk-move       # mailboxId = 哪个邮箱
Authorization: Bearer <token>                  # 身份「谁在操作」从请求头来，不放进 body
Body {
  search_result_token: "sr_123",               # 移「哪些」邮件（那批搜索结果）
  destination_folder_id: "newsletter"          # 移「到哪个」文件夹
}
→ 202 Accepted { job_id: "job_9", status: "queued" }   # 已受理，给作业号

# ② 查进度
GET /v1/bulk-move-jobs/{job_id}
→ { status:"running", total_count, processed_count, success_count, fail_count }

# ③ 分页拉每封的明细
GET /v1/bulk-move-jobs/{job_id}/items?page_size=50&cursor=...
→ { items:[ {message_id, status} ], next_cursor }
